{"nodes":[{"id":"c360.semsource.golang.workspace.function.processor-supersession-lifecycle-go-decideLifecycleActions","body":"func decideLifecycleActions(inScope []gtypes.EntityState, rootPath, reason string, stat func(path string) bool) (toMark []message.Triple, toClear []string, pathCount int) {
	if rootPath == "" {
		// No filesystem to check — the source itself is gone, so every
		// in-scope entity is unconditionally stale.
		for i := range inScope {
			if isMarkedStale(inScope[i].Triples) {
				continue
			}
			toMark = append(toMark, staleTriple(inScope[i].ID, reason))
		}
		return toMark, toClear, 0
	}

	byPath := make(map[string][]gtypes.EntityState)
	for i := range inScope {
