	cursor := s.start
	found := false
	for _, blk := range blocksOf(lines, s) {
		groups := keyValueGroups(lines, blk)
		if groups == nil {
			continue
		}
		found = true
		if groups[0][0] > cursor {
			out = append(out, [2]int{cursor, groups[0][0]})
		}
		out = append(out, groups...)
		cursor = groups[len(groups)-1][1]
	}
	if !found {
		return nil
	}
	if cursor < s.end {
		out = append(out, [2]int{cursor, s.end})
	}
	return out
}"},{"id":"c360.semsource.golang.workspace.function.handler-doc-dilution_margin_test-go-TestScorecardAnswerPassagesStayDivided","body":"func TestScorecardAnswerPassagesStayDivided(t *testing.T) {
