{"nodes":[{"id":"c360.semsource.golang.workspace.function.entityid-entityid-go-SanitizeInstance","body":"func SanitizeInstance(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		if isAllowedInstanceRune(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	out := b.String()
	for strings.Contains(out, "--") {
		out = strings.ReplaceAll(out, "--", "-")
	}
	out = strings.TrimFunc(out, func(r rune) bool { return !isASCIIAlnum(r) })

	if out == "" {
		return shortHash(s)
	}
	if len(out) > maxInstanceLen {
		suffix := shortHash(s)
		prefix := strings.TrimRightFunc(out[:maxInstanceLen-len(suffix)-1],
			func(r rune) bool { return !isASCIIAlnum(r) })
		if prefix == "" {
			return suffix
		}
		return prefix + "-" + suffix
	}
	return out
}"},{"id":"c360.semsource.golang.workspace.function.entityid-entityid-go-SanitizeSegment","body":"func SanitizeSegment(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		if isAllowedInstanceRune(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	out := strings.TrimLeftFunc(b.String(), func(r rune) bool { return !isASCIIAlnum(r) })
	if out == "" {
		return shortHash(s)
	}
	if out == s {
		return out
	}
	return out + "-" + shortHash(s)
}"},{"id":"c360.semsource.golang.workspace.function.source-ast-entities-go-SanitizePathSegment","body":"func SanitizePathSegment(path string) string {
