	// Project and version whose individual slugs are each under 80 but whose
	// join exceeds 80: 50 + 1 + 40 = 91 > maxSystemSlugLen (80).
	longProject := strings.Repeat("x", 50)
	version1 := strings.Repeat("y", 40)
	version2 := strings.Repeat("z", 40) // same length, different chars → different hash

	// Confirm the bug precondition: the raw join is >80. Concatenate directly —
	// VersionScopedSlug now caps its own join, so it is no longer the raw
	// primitive this precondition needs.
	rawJoined := entityid.SystemSlug(longProject) + "-" + entityid.SystemSlug(version1)
	if len(rawJoined) <= 80 {
		t.Fatalf("test precondition failed: raw joined slug is %d chars (≤80); "+
			"adjust inputs to exceed maxSystemSlugLen", len(rawJoined))
	}
	// Without the outer cap, SystemSlug applied after produces a DIFFERENT string
	// (truncation + hash kicks in), proving the defined-symbol path would disagree
	// with the referenced-symbol path.
	if entityid.SystemSlug(rawJoined) == rawJoined {
		t.Fatalf("test precondition failed: SystemSlug(rawJoined) is already "+
			"idempotent on the %d-char join — bug would not manifest", len(rawJoined))
	}

	slug1 := entityid.ScopedSystemSlug(longProject, version1)
	slug2 := entityid.ScopedSystemSlug(longProject, version2)

	// Property 1: result is ≤ maxSystemSlugLen (80) — length cap enforced.
	if len(slug1) > 80 {
		t.Errorf("ScopedSystemSlug result length = %d, want ≤ 80", len(slug1))
	}

	// Property 2: result is idempotent under SystemSlug — the NewScopedCodeEntity
	// path and the raw parser.go:503/551 path now produce the same system segment.
	if got := entityid.SystemSlug(slug1); got != slug1 {
		t.Errorf("ScopedSystemSlug result is not idempotent under SystemSlug:\n"+
			"  SystemSlug(%q)\n  = %q\n  (defined-symbol path disagrees with referenced-symbol path)",
			slug1, got)
	}

	// Property 3: distinct long versions produce distinct final slugs — the
	// content-hash suffix in SystemSlug's truncation preserves uniqueness.
	if slug1 == slug2 {
		t.Errorf("distinct long versions produced the same slug %q — "+
			"cross-version distinctness lost after length cap", slug1)
	}
}"},{"id":"c360.semsource.golang.workspace.function.entityid-entityid-go-SystemSlug","body":"func SystemSlug(canonicalPath string) string {
	// Strip URL scheme if present so "https://host/path" becomes "host/path".
	if parsed, err := url.Parse(canonicalPath); err == nil && parsed.Host != "" {
		canonicalPath = parsed.Host + parsed.Path
	}
	canonicalPath = strings.TrimSuffix(canonicalPath, ".git")
	canonicalPath = strings.TrimPrefix(canonicalPath, "./")

	// For absolute filesystem paths, use only the base name. Workspace-
	// cloned repos already have a meaningful slug as their directory name
	// (e.g. "github-com-opensensorhub-osh-core"), so the parent hierarchy
	// (temp dirs, user home, etc.) is noise that inflates entity IDs.
	if filepath.IsAbs(canonicalPath) {
		canonicalPath = filepath.Base(canonicalPath)
	}

	// Map any character outside the entity-ID allowlist ([A-Za-z0-9_-]) to a
	// hyphen. This is an ALLOWLIST, not a denylist: a denylist (only /,:,.) let
	// '@' through from Go module-cache paths (e.g. "semstreams@v1.2.3"), which
	// produced invalid NATS KV keys and failed component-name validation. Dots
	// break the 6-part ID's segment separator, so they map here too.
	var b strings.Builder
	b.Grow(len(canonicalPath))
	for _, r := range canonicalPath {
		if isAllowedInstanceRune(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	slug := b.String()
	for strings.Contains(slug, "--") {
		slug = strings.ReplaceAll(slug, "--", "-")
	}
	// Trim to an alphanumeric boundary so the slug is a valid ID segment
	// (^[A-Za-z0-9]…): a leading/trailing '-' or '_' would violate it.
	slug = strings.TrimFunc(slug, func(r rune) bool { return !isASCIIAlnum(r) })

	// Safety cap: truncate and append a short content hash when the slug
	// still exceeds the limit (e.g. extremely long directory names).
	if len(slug) > maxSystemSlugLen {
		h := sha256.Sum256([]byte(slug))
		suffix := hex.EncodeToString(h[:3]) // 6 hex chars
		slug = slug[:maxSystemSlugLen-7] + "-" + suffix
	}

	return slug
}"},{"id":"c360.semsource.golang.workspace.function.entityid-entityid-go-BranchScopedSlug","body":"func BranchScopedSlug(systemSlug, branchSlug string) string {
