	for id, name := range map[string]string{base: "BaseClient", sub: "AsyncClient", file: "client.py"} {
		g.AddEntity(id, map[string]any{
			ast.DcTitle: name, ast.CodeType: "class", ast.CodePath: "client.py",
			ast.CodeStartLine: 1, ast.CodeEndLine: 5, ontology.ClassPredicate: cco.Algorithm,
		})
	}
	// A real dependent (subclass) AND a structural container of the seed.
	g.AddEdge(sub, ast.CodeExtends, base)
	g.AddEdge(file, ast.CodeContains, base)
	g.SetResolve("BaseClient", base)

	engine := fusion.NewEngine(g, fusion.NewBodyResolver(fusion.MapStoreResolver{}))
	resp, err := engine.Fuse(context.Background(),
		fusion.Request{Query: "BaseClient", Want: []fusion.Want{fusion.WantRelations, fusion.WantImpact}},
		New())
	if err != nil {
		t.Fatal(err)
	}

	// Impact = ONLY the subclass; the containing file is excluded.
	if resp.Impact == nil || resp.Impact.Nodes != 1 {
		t.Fatalf("expected impact closure of 1 (the subclass, not the container), got %+v", resp.Impact)
	}

	// Relations still expose the container role — containment is scoped out of
	// impact, not dropped entirely.
	n := resp.Nodes[0]
	if got := n.Relations["container"]; len(got) != 1 || got[0].Name != "client.py" {
		t.Fatalf("container relation = %+v; want single client.py", got)
	}
	if got := n.Relations["extended_by"]; len(got) != 1 || got[0].Name != "AsyncClient" {
		t.Fatalf("extended_by relation = %+v; want single AsyncClient", got)
	}
}"},{"id":"c360.semsource.golang.workspace.function.handler-doc-handler_test-go-TestDocHandler_IngestEntityStates_FiltersByExtension","body":"func TestDocHandler_IngestEntityStates_FiltersByExtension(t *testing.T) {
	dir := t.TempDir()
	writeMD(t, dir, "valid.md", "# Doc\nContent.")
	writeMD(t, dir, "guide.mdx", "# MDX Guide\nSome MDX content.")
	writeMD(t, dir, "spec.adoc", "= AsciiDoc Spec\nSome AsciiDoc content.")
	// Non-doc file — should be ignored by the doc handler.
	if err := os.WriteFile(filepath.Join(dir, "main.go"), []byte("package main"), 0644); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	h, _ := docsHandler(t)
	cfg := sourceConfig{typ: "docs", path: dir}

	states, err := h.IngestEntityStates(context.Background(), cfg, "acme")
	if err != nil {
		t.Fatalf("IngestEntityStates() error: %v", err)
	}
	if parents := parentStates(states); len(parents) != 3 {
		t.Fatalf("parent state count: got %d, want 3 (.adoc + .md + .mdx); %d states in total",
			len(parents), len(states))
	}

	seen := filePathSet(t, states)
	for _, want := range []string{"valid.md", "guide.mdx", "spec.adoc"} {
		if !seen[want] {
			t.Errorf("expected %s %q among the states, not found; seen: %v", source.DocFilePath, want, seen)
		}
	}
	if seen["main.go"] {
		t.Errorf("main.go must not enter the docs corpus; seen: %v", seen)
	}
	if len(seen) != 3 {
		t.Errorf("distinct %s values: got %d %v, want 3 (no file beyond the three documents)",
			source.DocFilePath, len(seen), seen)
	}
}"},{"id":"c360.semsource.golang.workspace.function.workspace-workspace_test-go-TestIsPathReady_AcceptsExistingFile","body":"func TestIsPathReady_AcceptsExistingFile(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "go.mod")
	if err := os.WriteFile(file, []byte("module example.com/x\n"), 0o644); err != nil {
		t.Fatalf("write fixture: %v", err)
	}

	if err := workspace.IsPathReady(file); err != nil {
		t.Errorf("workspace.IsPathReady(regular file) = %v, want nil — a file that exists is ready", err)
	}
	// The directory-only contract is unchanged, and that is the point: ast-source
	// and git-source still need a non-directory to be an error.
	if err := workspace.IsRepoReady(file); err == nil {
		t.Error("workspace.IsRepoReady(regular file) = nil; its documented directory contract must not have been relaxed")
	}
}"},{"id":"c360.semsource.golang.workspace.struct.source-ast-golang-imports-go-pkgTypesEntry","body":"type pkgTypesEntry struct {
